import math

def P(x):
    # Candidate polynomial derived by W3, round 1
    return x**3 - 4049 * x**2 + 4098601 * x - 2024

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

n_values = list(range(-5, 6))
results = {}
counterexamples = []

print("Testing P(n) for n in [-5, ..., 5]:")
for n in n_values:
    p_n = P(n)
    is_sq = is_square(p_n)
    results[n] = (p_n, is_sq)

    if is_sq:
        # Check if this is a counterexample to the "only if" condition
        if n != 2024 and n != 2025:
            counterexamples.append((n, p_n))

# Print detailed results
for n, (p_n, is_sq) in results.items():
    print(f"P({n}) = {p_n}, Is Square: {is_sq}")

print("\n--- Summary ---")
if counterexamples:
    print("Found counterexamples to the 'only if' condition:")
    for n, p_n in counterexamples:
        print(f"n = {n}, P(n) = {p_n} (which is a perfect square)")
else:
    print("No counterexamples found in the tested range.")

